// "Reference Files": which reference datasets to download (same files the Part 1 RAG app uses).
const base = $('Config').first().json.reference_base_url.replace(/\/$/, '');
return [
  { name: 'road_register', file: 'road_register.csv' },
  { name: 'hotspots', file: 'hotspots.csv' },
  { name: 'hazard_rules', file: 'hazard_response_rules.json' },
  { name: 'inspectors', file: 'inspectors.csv' },
].map(f => ({ json: { ...f, url: `${base}/${f.file}` } }));

// "Prepare Emails": one clean item per complaint email for the LLM.
return $('Get Hazard Emails').all().map(i => {
  const m = i.json;
  const body = (m.text || m.textPlain || m.snippet || '').replace(/\r/g, '');
  const clean = body.split(/\n(?:On .+wrote:|Op .+geskryf:|-{2,} ?Original Message)/)[0].trim().slice(0, 6000);
  return { json: {
    email_id: m.id, subject: m.subject || '', from: m.from?.value?.[0]?.address || '',
    received: m.date ? new Date(m.date).toISOString() : new Date().toISOString(), body: clean } };
});

// "Parse, Ground & Normalise" (Run Once for All Items)
// Parses the LLM extraction, checks every extracted value against the source email (grounding),
// normalises contacts, and maps road names (incl. Afrikaans/abbreviations) onto the road register.
const emails = $('Prepare Emails').all().map(i => i.json);
const ref = Object.fromEntries($('Fetch Reference Data').all().map((r, i) => [$('Reference Files').all()[i].json.name, r.json.data]));

function parseCsv(text) {
  const rows = []; let row = [], cur = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"' && text[i + 1] === '"') { cur += '"'; i++; } else if (c === '"') q = false; else cur += c; }
    else if (c === '"') q = true; else if (c === ',') { row.push(cur); cur = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cur); rows.push(row); row = []; cur = ''; }
    else cur += c;
  }
  if (cur || row.length) { row.push(cur); rows.push(row); }
  const [head, ...body] = rows.filter(r => r.some(x => x.trim()));
  return body.map(r => Object.fromEntries(head.map((h, i) => [h.trim(), (r[i] || '').trim()])));
}
const roads = parseCsv(ref.road_register);
const rules = JSON.parse(ref.hazard_rules).hazard_types;
const CODES = new Set(rules.map(r => r.hazard_code));

// "Voortrekkerweg" -> "voortrekker road", "Durban Rd" -> "durban road", "Jan Smutsrylaan" -> "jan smuts drive"
function canonRoad(s) {
  if (!s) return '';
  let x = String(s).toLowerCase().replace(/[.,]/g, ' ').replace(/\s+/g, ' ').trim();
  x = x.replace(/(\S)(weg|straat|rylaan|laan)$/, '$1 $2');
  const SUF = { rd: 'road', road: 'road', weg: 'road', st: 'street', str: 'street', street: 'street', straat: 'street',
                dr: 'drive', drive: 'drive', rylaan: 'drive', ave: 'avenue', avenue: 'avenue', laan: 'avenue' };
  const parts = x.split(' ');
  const last = parts[parts.length - 1];
  if (SUF[last]) parts[parts.length - 1] = SUF[last];
  return parts.join(' ').replace(/^the /, '');
}
const regNames = [...new Set(roads.map(r => r.road_name))];
function matchRegister(name) {
  const c = canonRoad(name);
  if (!c) return null;
  const exact = regNames.find(r => r.toLowerCase() === c);
  if (exact) return exact;
  const stem = c.replace(/ (road|street|drive|avenue)$/, '');
  return regNames.find(r => r.toLowerCase().replace(/ (road|street|drive|avenue)$/, '') === stem) || null;
}
const titleCase = s => s.replace(/\b([a-z])/g, m => m.toUpperCase());
const digits = s => String(s || '').replace(/\D/g, '');
function normPhone(raw, log) {
  if (!raw) return '';
  let d = String(raw).replace(/\(0\)/g, '').replace(/\D/g, '');
  if (d.startsWith('0') && d.length === 10) d = '27' + d.slice(1);
  if (d.startsWith('270') && d.length === 12) d = '27' + d.slice(3);
  if (/^27\d{9}$/.test(d)) { if ('+' + d !== raw) log.push(`phone "${raw}" -> +${d}`); return '+' + d; }
  log.push(`phone "${raw}" is not a valid SA number - kept for review`); return String(raw);
}
const strip = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

const out = [];
$input.all().forEach((item, idx) => {
  const src = emails[idx] || {};
  const base = { email_id: src.email_id, subject: src.subject, received: src.received, log: [], flags: [] };
  let x;
  try { x = JSON.parse(String(item.json.text).replace(/```json|```/g, '').trim()); }
  catch (e) { out.push({ json: { ...base, kind: 'parse_error', geocode_query: '', flags: ['LLM output was not valid JSON - needs manual review'] } }); return; }
  if (!x.is_road_report) { out.push({ json: { ...base, kind: 'not_road_report', reason: x.reason || '', geocode_query: '' } }); return; }

  const text = strip(`${src.subject} ${src.body}`);
  const log = base.log, flags = base.flags;
  // --- grounding: anything the model claims must be traceable to the email text
  const loc = x.location || {}, res = x.resident || {};
  for (const [k, v] of [['road', loc.road], ['cross_street', loc.cross_street], ['suburb', loc.suburb]]) {
    if (!v) continue;
    const stem = strip(v).replace(/\b(road|rd|street|st|drive|dr|weg|straat|rylaan|avenue|ave)\b/g, '').trim().split(' ')[0];
    if (stem && !text.includes(stem)) { log.push(`LLM ${k} "${v}" not found in email - discarded`); loc[k] = ''; }
  }
  if (res.email && !text.includes(strip(res.email))) { log.push(`LLM email "${res.email}" not in source - discarded`); res.email = ''; }
  if (res.phone && !digits(text).includes(digits(res.phone).slice(-7))) { log.push(`LLM phone "${res.phone}" not in source - discarded`); res.phone = ''; }
  if (loc.house_number && !text.includes(String(loc.house_number))) { log.push(`house number "${loc.house_number}" not in source - discarded`); loc.house_number = ''; }
  let code = x.hazard_code;
  if (!CODES.has(code)) { flags.push(`unknown hazard type "${code}" - set to road_obstruction for review`); code = 'road_obstruction'; }

  // --- road names onto the register
  const road = matchRegister(loc.road), cross = matchRegister(loc.cross_street);
  if (road && road.toLowerCase() !== strip(loc.road)) log.push(`road "${loc.road}" -> "${road}"`);
  if (cross && cross.toLowerCase() !== strip(loc.cross_street)) log.push(`cross street "${loc.cross_street}" -> "${cross}"`);
  const roadName = road || (loc.road ? titleCase(canonRoad(loc.road)) : '');
  const crossName = cross || (loc.cross_street ? titleCase(canonRoad(loc.cross_street)) : '');
  const suburb = loc.suburb ? titleCase(String(loc.suburb).toLowerCase().trim()) : '';
  if (!roadName) flags.push('no usable street name in report');

  const email = (res.email || '').trim().toLowerCase();
  const geocode_query = roadName ? [loc.house_number, roadName].filter(Boolean).join(' ') + `, ${suburb ? suburb + ', ' : ''}Cape Town, South Africa` : '';
  out.push({ json: { ...base, kind: 'report', language: x.language || 'English', hazard_code: code,
    hazard_summary_en: x.hazard_summary_en || '', road: roadName, road_in_register: !!road, cross_street: crossName,
    house_number: loc.house_number || '', landmark: loc.landmark || '', suburb_reported: suburb,
    resident: { name: res.name ? titleCase(String(res.name).toLowerCase()) : '', email, phone: normPhone(res.phone, log) },
    danger_signals: x.danger_signals || [], geocode_query } });
});
return out;

// "Verify, Dedupe & Score" (Run Once for All Items)
// $input = Nominatim responses, index-aligned with "Parse, Ground & Normalise".
const items = $('Parse, Ground & Normalise').all().map(i => i.json);
const ref = Object.fromEntries($('Fetch Reference Data').all().map((r, i) => [$('Reference Files').all()[i].json.name, r.json.data]));
function parseCsv(text) {
  const rows = []; let row = [], cur = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"' && text[i + 1] === '"') { cur += '"'; i++; } else if (c === '"') q = false; else cur += c; }
    else if (c === '"') q = true; else if (c === ',') { row.push(cur); cur = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cur); rows.push(row); row = []; cur = ''; }
    else cur += c;
  }
  if (cur || row.length) { row.push(cur); rows.push(row); }
  const [head, ...body] = rows.filter(r => r.some(x => x.trim()));
  return body.map(r => Object.fromEntries(head.map((h, i) => [h.trim(), (r[i] || '').trim()])));
}
const roads = parseCsv(ref.road_register), hotspots = parseCsv(ref.hotspots), inspectors = parseCsv(ref.inspectors);
const rulesDoc = JSON.parse(ref.hazard_rules);
const rule = Object.fromEntries(rulesDoc.hazard_types.map(r => [r.hazard_code, r]));
const low = s => String(s || '').toLowerCase().trim();
const suburbArea = {};
inspectors.forEach(ins => ins.suburbs.split(';').forEach(s => { suburbArea[low(s)] = ins.area; }));
const toRad = d => d * Math.PI / 180;
const distM = (a, b, c, d) => { const R = 6371000, x = toRad(c - a), y = toRad(d - b);
  const h = Math.sin(x / 2) ** 2 + Math.cos(toRad(a)) * Math.cos(toRad(c)) * Math.sin(y / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(h)); };
const hash = s => { let h = 5381; for (const ch of s) h = ((h << 5) + h + ch.charCodeAt(0)) >>> 0; return h.toString(36).toUpperCase().slice(0, 6).padStart(6, '0'); };

const reports = [], other = [];
items.forEach((it, i) => {
  if (it.kind !== 'report') { other.push(it); return; }
  // ---- 1. map verification (OpenStreetMap / Nominatim)
  let geo = null;
  try { const g = JSON.parse($input.all()[i]?.json?.geo_raw || '[]'); geo = Array.isArray(g) && g.length ? g[0] : null; } catch (e) { geo = null; }
  it.geo = { status: 'not_found' };
  if (it.geocode_query && geo) {
    const a = geo.address || {};
    const osmRoad = a.road || a.pedestrian || '';
    const osmSuburb = a.suburb || a.neighbourhood || a.quarter || a.city_district || a.town || '';
    const roadOk = low(osmRoad).replace(/ (road|street|drive|avenue)$/, '') === low(it.road).replace(/ (road|street|drive|avenue)$/, '');
    it.geo = { status: roadOk ? 'verified' : 'partial', lat: +geo.lat, lon: +geo.lon, osm_road: osmRoad, osm_suburb: osmSuburb,
               precision: geo.addresstype || geo.type, display: geo.display_name };
    if (!roadOk) it.flags.push(`map lookup returned "${osmRoad || geo.display_name}" not "${it.road}" - location needs checking`);
    if (it.suburb_reported && osmSuburb && low(osmSuburb) !== low(it.suburb_reported) && !suburbArea[low(it.suburb_reported)])
      it.flags.push(`resident said "${it.suburb_reported}", map says "${osmSuburb}"`);
  } else if (it.geocode_query) it.flags.push('address could not be verified on the map');

  // ---- 2. area, road segment, hotspot
  const suburb = it.geo.osm_suburb || it.suburb_reported;
  const segs = roads.filter(r => low(r.road_name) === low(it.road));
  let seg = segs.find(r => r.suburbs.split(';').some(s => low(s) === low(suburb))) || (segs.length === 1 ? segs[0] : null);
  let area = suburbArea[low(suburb)] || seg?.area || '';
  if (!seg && segs.length > 1 && area) seg = segs.find(r => r.area === area);
  const crossSeg = roads.find(r => low(r.road_name) === low(it.cross_street) && (!area || r.area === area));
  const pair = [low(it.road), low(it.cross_street)].sort().join('|');
  let hs = hotspots.find(h => [low(h.road_a), low(h.road_b)].sort().join('|') === pair && (!area || h.area === area));
  let hsHow = hs ? 'intersection match' : '';
  if (!hs && it.geo.lat) {
    const near = hotspots.map(h => [h, distM(it.geo.lat, it.geo.lon, +h.lat, +h.lon)]).sort((a, b) => a[1] - b[1])[0];
    if (near && near[1] <= 200 && [low(near[0].road_a), low(near[0].road_b)].includes(low(it.road))) { hs = near[0]; hsHow = `within ${Math.round(near[1])} m`; }
  }
  if (!area && hs) area = hs.area;
  if (!seg && it.road) it.flags.push(`"${it.road}" not in road register - defaults used (local road, 60 km/h, medium pedestrian volume)`);
  if (!area) it.flags.push('could not determine area / inspector');
  Object.assign(it, { area, suburb, seg, crossSeg, hs, hsHow,
    lat: hs ? +hs.lat : it.geo.lat, lon: hs ? +hs.lon : it.geo.lon });
  reports.push(it);
});

// ---- 3. deduplicate: same hazard + same place (intersection pair, house number, or <=120 m)
const placeKey = r => r.cross_street ? [low(r.road), low(r.cross_street)].sort().join('&') : `${low(r.road)}#${r.house_number || low(r.landmark) || ''}`;
const clusters = [];
for (const r of reports.filter(r => r.road)) {
  const c = clusters.find(c => c.hazard_code === r.hazard_code && (c.key === placeKey(r) ||
    (c.lat && r.lat && distM(c.lat, c.lon, r.lat, r.lon) <= 120 && low(c.reports[0].road) === low(r.road))));
  if (c) c.reports.push(r); else clusters.push({ hazard_code: r.hazard_code, key: placeKey(r), lat: r.lat, lon: r.lon, reports: [r] });
}
reports.filter(r => !r.road).forEach(r => clusters.push({ hazard_code: r.hazard_code, key: `nolocation#${r.email_id}`, reports: [r], incomplete: true }));

// ---- 4. risk score (formula published in hazard_response_rules.json)
const PED = { High: 1.5, Medium: 1.2, Low: 1.0 };
const now = Date.now();
const cases = clusters.map(c => {
  const r0 = c.reports.find(r => r.geo.status === 'verified') || c.reports.slice().sort((a, b) => a.received.localeCompare(b.received))[0];
  const rl = rule[c.hazard_code], seg = r0.seg, cs = r0.crossSeg, hs = r0.hs;
  const n = c.reports.length;
  let flags = [...new Set(c.reports.flatMap(r => r.flags))];
  if (c.reports.some(r => r.geo.status === 'verified')) flags = flags.filter(f => f !== 'address could not be verified on the map');
  const log = c.reports.flatMap(r => r.log.map(l => `${r.email_id}: ${l}`));
  if (n > 1) log.push(`merged ${n} reports of the same hazard (${c.reports.map(r => r.language).join(', ')})`);
  const speed = Math.max(+(seg?.speed_limit_kmh || 60), +(cs?.speed_limit_kmh || 0));
  const pedVol = [seg?.pedestrian_volume, cs?.pedestrian_volume].includes('High') ? 'High' : [seg?.pedestrian_volume, cs?.pedestrian_volume].includes('Medium') || !seg ? 'Medium' : 'Low';
  const fs = Math.round(speed / 60 * 100) / 100, fp = PED[pedVol];
  const fh = hs ? Math.min(3, Math.round((1 + 0.2 * +hs.fatal + 0.05 * +hs.serious) * 100) / 100) : 1;
  const fr = Math.min(1.5, Math.round((1 + 0.1 * (n - 1)) * 100) / 100);
  const score = Math.round(rl.severity * fs * fp * fh * fr * 10) / 10;
  const breakdown = `${rl.severity} severity (${c.hazard_code}) × ${fs} speed (${speed} km/h) × ${fp} pedestrians (${pedVol}) × ${fh} hotspot` +
    (hs ? ` (${hs.hotspot_id}: ${hs.fatal} fatal, ${hs.serious} serious)` : ' (none)') + ` × ${fr} reports (${n}) = ${score}`;
  let band = score >= 12 ? 'P1' : score >= 6 ? 'P2' : 'P3';
  const why = [];
  if (c.hazard_code === 'traffic_signal_outage' && hs && band !== 'P1') { band = 'P1'; why.push('override: signal outage at a hotspot is always P1'); }
  const national = [seg?.jurisdiction, cs?.jurisdiction].some(j => String(j || '').startsWith('National'));
  if (national) { band = 'REFERRED'; why.push('national road - referred to SANRAL'); }
  if (c.incomplete) { band = 'INCOMPLETE'; why.push('no location - resident asked for details'); }
  const capH = band === 'P1' ? 4 : band === 'P2' ? Math.min(48, rl.repair_deadline_hours) : rl.repair_deadline_hours;
  const first = Math.min(...c.reports.map(r => Date.parse(r.received) || now));
  const label = { P1: 'P1 - Urgent', P2: 'P2 - High', P3: 'P3 - Routine', REFERRED: 'REFERRED - SANRAL', INCOMPLETE: 'INCOMPLETE - needs location' }[band];
  const ins = inspectors.find(i => i.area === r0.area);
  const where = r0.road ? (r0.cross_street ? `${r0.road} & ${r0.cross_street}` : `${r0.house_number ? r0.house_number + ' ' : ''}${r0.road}${r0.landmark ? ' (' + r0.landmark + ')' : ''}`) + (r0.suburb ? `, ${r0.suburb}` : '') : 'Location not provided';
  return {
    case_id: 'SRD-' + hash(`${c.hazard_code}|${c.key}`), priority: label, band, risk_score: band === 'INCOMPLETE' ? 0 : score, score_breakdown: band === 'INCOMPLETE' ? 'not scored - location missing' : breakdown,
    priority_reason: why.join('; '), hazard_code: c.hazard_code, hazard_label: rl.description, department: national ? 'SANRAL (referral)' : rl.department,
    inspection_required: !national && !c.incomplete && (rl.inspection_required === true || band === 'P1' || band === 'P2'),
    location_text: where, road: r0.road, cross_street: r0.cross_street, suburb: r0.suburb, area: r0.area,
    lat: r0.lat ?? '', lon: r0.lon ?? '', geocode_status: r0.geo.status, hotspot_id: hs?.hotspot_id || '', hotspot_match: r0.hsHow,
    reports: n, languages: [...new Set(c.reports.map(r => r.language))].join(', '),
    first_reported: new Date(first).toISOString(), due_by: new Date(Math.max(first, now) + capH * 3600e3).toISOString(),
    inspector_id: ins?.inspector_id || '', inspector: ins?.name || '',
    residents: c.reports.map(r => ({ email_id: r.email_id, name: r.resident.name, email: r.resident.email, phone: r.resident.phone, language: r.language })),
    summary_en: r0.hazard_summary_en, danger_signals: [...new Set(c.reports.flatMap(r => r.danger_signals || []))].join('; '),
    flags: flags.join(' | '), corrections: log.join(' | '), sources: c.reports.map(r => `email:${r.email_id}`).join(' ; '),
  };
});
const order = { P1: 0, P2: 1, P3: 2, INCOMPLETE: 3, REFERRED: 4 };
cases.sort((a, b) => order[a.band] - order[b.band] || b.risk_score - a.risk_score);
const skipped = other.map(o => ({ email_id: o.email_id, subject: o.subject, kind: o.kind, reason: o.reason || o.flags?.join('; ') || '' }));
return cases.map((c, i) => ({ json: { ...c, _skipped: i === 0 ? skipped : undefined } }));

// "Schedule Inspections" (Run Once for All Items)
// Reads inspectors' existing calendar events (busy blocks + already-booked cases) and books the earliest free
// 1-hour slot per case, in priority order, inside Mon-Fri 08:00-16:00 SAST. Idempotent: a case that already has
// an event is not booked twice.
const cases = $('Verify, Dedupe & Score').all().map(i => i.json);
const events = $('Read Inspector Calendar').all().map(i => i.json).filter(e => e.summary && e.start);
const OFF = 2 * 3600e3; // SAST = UTC+2, no daylight saving
const sast = ms => new Date(ms + OFF);
const iso = ms => { const d = sast(ms); return d.toISOString().slice(0, 19) + '+02:00'; };
const pretty = ms => { const d = sast(ms); return `${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d.getUTCDay()]} ${d.getUTCDate()} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][d.getUTCMonth()]} ${String(d.getUTCHours()).padStart(2,'0')}:00`; };
const t = e => Date.parse(e.dateTime || e.date);

const busy = {};   // inspector -> [[start,end]]
const booked = {}; // case_id -> event
for (const e of events) {
  const m = e.summary.match(/\[(INS-\d+)\]/);
  if (m) (busy[m[1]] ||= []).push([t(e.start), t(e.end)]);
  const c = e.summary.match(/SRD-[0-9A-Z]{6}/);
  if (c) booked[c[0]] = e;
}
function nextSlot(ins, fromMs) {
  let d = sast(fromMs); d.setUTCMinutes(0, 0, 0);
  let ms = d.getTime() - OFF + 3600e3; // next full hour
  for (let k = 0; k < 24 * 10; k++, ms += 3600e3) {
    const s = sast(ms), h = s.getUTCHours(), wd = s.getUTCDay();
    if (wd === 0 || wd === 6 || h < 8 || h > 15) continue;
    const clash = (busy[ins] || []).some(([a, b]) => ms < b && ms + 3600e3 > a);
    if (!clash) return ms;
  }
  return null;
}
const COLOR = { P1: '11', P2: '6', P3: '9' };
const now = Date.now();
return cases.map(c => {
  const out = { ...c, inspection_start: '', start_iso: '', end_iso: '', calendar_action: 'none', schedule_note: '' };
  if (!c.inspection_required || !c.inspector_id) { out.schedule_note = c.inspection_required ? 'no inspector for area' : 'no inspection needed'; return { json: out }; }
  const existing = booked[c.case_id];
  if (existing) {
    const s = t(existing.start);
    Object.assign(out, { inspection_start: pretty(s), start_iso: iso(s), end_iso: iso(t(existing.end)), calendar_action: 'exists',
                         schedule_note: 'already booked in a previous run - not double-booked' });
    return { json: out };
  }
  const s = nextSlot(c.inspector_id, now);
  if (s === null) { out.schedule_note = 'no free slot in the next 10 days'; out.flags = [c.flags, 'no inspector slot available'].filter(Boolean).join(' | '); return { json: out }; }
  (busy[c.inspector_id] ||= []).push([s, s + 3600e3]);
  const late = s > Date.parse(c.due_by);
  Object.assign(out, {
    inspection_start: pretty(s), start_iso: iso(s), end_iso: iso(s + 3600e3), calendar_action: 'create',
    schedule_note: late ? `earliest slot is after the ${c.band} deadline - escalate to standby inspector` : 'within deadline',
    event_summary: `[${c.inspector_id}] ${c.band} inspect: ${c.hazard_label.split(' or ')[0]} - ${c.location_text} (${c.case_id})`,
    event_description: [`Case ${c.case_id} · ${c.priority} · risk score ${c.risk_score}`, `Score: ${c.score_breakdown}`,
      c.priority_reason && `Why: ${c.priority_reason}`, `Reports: ${c.reports} (${c.languages})`, `Summary: ${c.summary_en}`,
      c.hotspot_id && `Crash hotspot: ${c.hotspot_id} (${c.hotspot_match})`, `Due by: ${pretty(Date.parse(c.due_by))}`,
      c.lat && `Map: https://www.openstreetmap.org/?mlat=${c.lat}&mlon=${c.lon}#map=18/${c.lat}/${c.lon}`,
      c.flags && `Flags: ${c.flags}`].filter(Boolean).join('\n'),
    event_color: COLOR[c.band] || '8',
  });
  if (late) out.flags = [c.flags, 'inspection slot later than deadline'].filter(Boolean).join(' | ');
  return { json: out };
});

// "Sheet Rows": flatten cases for the Command Centre Google Sheet (one row per case, upserted on case_id).
const prev = Object.fromEntries($('Read Existing Cases').all().map(i => i.json).filter(r => r.case_id)
  .map(r => [r.case_id, String(r.replied_email_ids || '')]));
return $('Schedule Inspections').all().map(({ json: c }) => {
  const replied = new Set(String(prev[c.case_id] || '').split(';').filter(Boolean));
  c.residents.filter(r => r.email || c.band === 'INCOMPLETE').forEach(r => replied.add(r.email_id));
  return { json: {
    case_id: c.case_id, priority: c.priority, risk_score: c.risk_score, score_breakdown: c.score_breakdown,
    priority_reason: c.priority_reason, hazard_code: c.hazard_code, hazard_label: c.hazard_label, department: c.department,
    location_text: c.location_text, road: c.road, cross_street: c.cross_street, suburb: c.suburb, area: c.area,
    lat: c.lat, lon: c.lon, geocode_status: c.geocode_status, hotspot_id: c.hotspot_id, reports: c.reports,
    languages: c.languages, inspector: c.inspector, inspection_start: c.inspection_start, schedule_note: c.schedule_note,
    first_reported: c.first_reported, due_by: c.due_by, flags: c.flags, corrections: c.corrections, sources: c.sources,
    residents: c.residents.map(r => `${r.name || '?'} <${r.email || 'no email'}>`).join('; '),
    replied_email_ids: [...replied].join(';'), updated_at: new Date().toISOString(),
  } };
});

// "Build Report": HTML dashboard email + CSV attachment (binary from "Convert to CSV").
const cfg = $('Config').first().json;
const cases = $('Schedule Inspections').all().map(i => i.json);
const skipped = $('Verify, Dedupe & Score').first().json._skipped || [];
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const C = { P1: '#dc2626', P2: '#d97706', P3: '#2563eb', REFERRED: '#6b7280', INCOMPLETE: '#9333ea' };
const n = b => cases.filter(c => c.band === b).length;
const reports = cases.reduce((s, c) => s + c.reports, 0);
const tile = (label, v, col) => `<td style="padding:10px 16px;border:1px solid #e5e7eb;text-align:center"><div style="font-size:22px;font-weight:bold;color:${col}">${v}</div><div style="font-size:11px;color:#6b7280">${label}</div></td>`;
const rows = cases.map(c => `<tr>
<td><span style="background:${C[c.band]};color:#fff;padding:2px 6px;border-radius:4px;font-size:11px">${esc(c.priority)}</span><br><span style="font-size:11px">${c.case_id}</span></td>
<td><b>${esc(c.hazard_label)}</b><br>${esc(c.location_text)}${c.hotspot_id ? `<br><span style="color:#dc2626">⚠ crash hotspot ${c.hotspot_id}</span>` : ''}</td>
<td style="text-align:center">${c.risk_score}</td><td style="text-align:center">${c.reports}<br><span style="font-size:10px">${esc(c.languages)}</span></td>
<td>${esc(c.inspector)}<br>${esc(c.inspection_start || c.schedule_note)}</td>
<td style="font-size:11px">${esc(c.score_breakdown)}${c.priority_reason ? '<br><i>' + esc(c.priority_reason) + '</i>' : ''}</td>
<td style="font-size:11px;color:#b45309">${esc(c.flags)}</td></tr>`).join('\n');
const html = `<div style="font-family:Arial,sans-serif;max-width:1100px">
<h2 style="margin-bottom:4px">🚦 Safer Roads Desk: hazard run report</h2>
<div style="color:#6b7280;font-size:12px">${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC · synthetic demo data</div>
<table style="border-collapse:collapse;margin:14px 0"><tr>${tile('Emails read', reports + skipped.length, '#111')}${tile('Unique hazards', cases.length, '#111')}
${tile('Duplicates merged', reports - cases.length, '#111')}${tile('P1 urgent', n('P1'), C.P1)}${tile('P2 high', n('P2'), C.P2)}${tile('P3 routine', n('P3'), C.P3)}
${tile('Referred', n('REFERRED'), C.REFERRED)}${tile('Incomplete', n('INCOMPLETE'), C.INCOMPLETE)}</tr></table>
${cfg.command_centre_url ? `<p><a href="${cfg.command_centre_url}">Open the live Command Centre map →</a></p>` : ''}
<table border="1" cellpadding="6" style="border-collapse:collapse;font-size:12px;border-color:#e5e7eb">
<tr style="background:#f3f4f6"><th>Priority</th><th>Hazard & location</th><th>Risk</th><th>Reports</th><th>Inspection</th><th>Why this score</th><th>Flags</th></tr>
${rows}</table>
${skipped.length ? `<p style="font-size:12px;color:#6b7280">Not processed as road hazards: ${skipped.map(s => esc(`"${s.subject}" (${s.kind}${s.reason ? ': ' + s.reason : ''})`)).join('; ')}</p>` : ''}
<p style="font-size:11px;color:#9ca3af">Every value extracted by the AI was checked against the source email; full audit trail in the attached CSV ("corrections" column).</p></div>`;
return [{ json: { subject: `[Safer Roads Desk] Run report: ${n('P1')} urgent, ${cases.length} hazards`, html }, binary: $input.first().binary }];

// "Reply Targets": one acknowledgement per resident not yet replied to (state read from the sheet).
const cfg = $('Config').first().json;
const prev = new Set($('Read Existing Cases').all().map(i => i.json).filter(r => r.case_id)
  .flatMap(r => String(r.replied_email_ids || '').split(';')).filter(Boolean));
const out = [];
for (const { json: c } of $('Schedule Inspections').all()) {
  for (const r of c.residents) {
    if (prev.has(r.email_id) || !r.email) continue;
    const kind = c.band === 'INCOMPLETE' ? 'need_location' : c.band === 'REFERRED' ? 'referred' : 'acknowledge';
    out.push({ json: {
      kind, case_id: c.case_id, language: r.language || 'English', resident_name: r.name, resident_email: r.email,
      hazard: c.hazard_label, location: c.location_text, priority: c.priority, inspection: c.inspection_start, due_by: c.due_by,
      send_to: String(cfg.demo_mode) === 'true' ? cfg.report_to : r.email,
      subject: `[Safer Roads Desk] Ref ${c.case_id}` + (String(cfg.demo_mode) === 'true' ? ` (demo: would go to ${r.email})` : ''),
    } });
  }
}
return out.length ? out : [{ json: { kind: 'none' } }];

parameters.text:
=Write a short, warm email reply from a municipal roads desk to a resident. Write it ENTIRELY in {{ $json.language }}
(if the language is isiXhosa write in isiXhosa, if Afrikaans write in Afrikaans; otherwise English).
Maximum 110 words. Plain text only, no subject line. Do not mention risk scores or internal priorities.

Facts to use:
- Resident name: {{ $json.resident_name || 'resident' }}
- Reference number: {{ $json.case_id }}
- Problem: {{ $json.hazard }} at {{ $json.location }}
- Situation: {{ $json.kind }}
  * acknowledge: thank them; say an inspector is scheduled for {{ $json.inspection || 'the coming days' }} and that urgent safety issues are prioritised.
  * need_location: thank them; explain we could not tell where the problem is and ask for the street name and nearest cross street or landmark, replying to this email.
  * referred: thank them; explain this road is a national road managed by SANRAL and the report has been forwarded to them.
- Sign off as: Safer Roads Desk (demo)
If Situation is "none", reply with an empty string.

parameters.jsCode:
// "Assemble Replies": pair each LLM-drafted reply with its target (same order).
const targets = $('Reply Targets').all().map(i => i.json);
return $input.all()
  .map((it, i) => ({ ...targets[i], body: String(it.json.text || '').trim() }))
  .filter(r => r.kind && r.kind !== 'none' && r.body)
  .map(r => ({ json: r }));
